<style>
.business-editor-grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(360px,5fr);gap:24px;align-items:start}.business-editor-preview{position:sticky;top:100px;min-width:0}.business-editor-content{min-width:0}.business-editor-content .catalog-editor,.business-editor-content .directory-editor{max-width:none}.business-editor-content section,.business-editor-content details{box-shadow:0 4px 18px rgba(15,23,42,.025)}.business-editor-content summary{display:flex;align-items:center;gap:10px;min-height:30px}.business-editor-content .action,.business-editor-content button{transition:background .2s,box-shadow .2s}.business-editor-content button:hover{box-shadow:0 3px 10px rgba(61,107,255,.15)}.business-editor-content input:focus-visible,.business-editor-content select:focus-visible,.business-editor-content textarea:focus-visible{outline:2px solid var(--accent,#3d6bff);outline-offset:2px}.business-editor-content .sb-grid{display:block}.business-editor-content .fields{grid-template-columns:repeat(2,minmax(0,1fr))}
@media(max-width:1000px){.business-editor-grid{grid-template-columns:minmax(0,1fr)}.business-editor-preview{position:static}}@media(max-width:600px){.business-editor-content .fields{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.business-editor-content button,.business-editor-content .action{transition:none}}
</style>
